import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    z = [0] * n
    l = r = 0
    for i in range(1, n):
        k = 0
        if i < r:
            k = min(r - i, z[i - l])
        while i + k < n and s[k] == s[i + k]:
            k += 1
        z[i] = k
        if i + k > r:
            l, r = i, i + k
    out = [s[0]]
    i = 1
    while i < n:
        if z[i] >= i:
            out.append('*')
            i += i
        else:
            out.append(s[i])
            i += 1
    print(''.join(out))

main()

